'use client';
import { useState } from 'react';
import { FiMenu, FiX } from 'react-icons/fi';

const DocBot = () => {
  const [chat, setChat] = useState('');
  const [messages, setMessages] = useState<{ user: string; bot: string }[]>([]);
  const [fileName, setFileName] = useState('');
  const [sidebarOpen, setSidebarOpen] = useState(false);

  const handleSend = async () => {
    if (!chat.trim()) return;
    setMessages([...messages, { user: chat, bot: 'Thinking...' }]);
    setChat('');
    // Simulate a bot response
    setTimeout(() => {
      setMessages((prev) => prev.slice(0, -1).concat({ user: chat, bot: 'Here is your AI-generated answer!' }));
    }, 1000);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setFileName(file.name);
      setMessages([...messages, { user: 'Uploaded File', bot: 'Processing file...' }]);
      setTimeout(() => {
        setMessages((prev) => prev.slice(0, -1).concat({ user: 'Uploaded File', bot: 'File processed successfully!' }));
      }, 1500);
    }
  };

  const downloadChat = () => {
    const chatContent = messages.map(msg => `User: ${msg.user}\nBot: ${msg.bot}\n`).join('\n');
    const blob = new Blob([chatContent], { type: 'text/plain' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = 'chat_history.txt';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="flex h-screen bg-gray-100">
      {/* Sidebar */}
      <div className={`fixed top-0 left-0 h-full bg-white shadow-lg transition-transform duration-300 ${sidebarOpen ? 'translate-x-0' : '-translate-x-full'}`} style={{ width: '250px' }}>
        <div className="p-4 flex flex-col h-full">
          <button onClick={() => setSidebarOpen(false)} className="text-xl mb-4 self-end">
            <FiX />
          </button>
          <h2 className="text-xl font-semibold">Upload PDF</h2>
          <input type="file" accept=".pdf" id="file-upload" style={{ display: 'none' }} onChange={handleFileUpload} />
          <label htmlFor="file-upload" className="bg-blue-500 text-white px-4 py-2 rounded-lg cursor-pointer text-center w-full hover:bg-blue-600 transition mt-2">📎 Upload File</label>
          {fileName && <p className="mt-4 text-sm text-gray-700">Uploaded: {fileName}</p>}
          <button onClick={downloadChat} className="mt-6 bg-green-500 text-white px-4 py-2 rounded-lg hover:bg-green-600 transition w-full">⬇️ Download Chat</button>
        </div>
      </div>

      {/* Hamburger Button */}
      <button onClick={() => setSidebarOpen(true)} className="fixed top-4 left-4 bg-gray-800 text-white p-2 rounded-md">
        <FiMenu size={24} />
      </button>

      {/* Main Chat Section */}
      <div className="flex flex-col w-full items-center justify-center px-6">
        <h1 className="text-3xl font-bold my-4">📚 Chat with Your PDF</h1>
        
        {/* Chat Box */}
        <div className="w-full max-w-3xl bg-white shadow-lg rounded-lg p-6 h-[500px] overflow-y-auto border">
          {messages.length === 0 ? (
            <p className="text-center text-gray-500">No chat history. Ask a question!</p>
          ) : (
            messages.map((msg, index) => (
              <div key={index} className={`flex ${msg.user === 'Uploaded File' ? 'justify-center' : 'justify-start'} mb-3`}>
                <div className={`p-3 rounded-lg shadow-md ${msg.user === 'Uploaded File' ? 'bg-gray-200' : 'bg-blue-100'}`}>
                  <p className="text-sm text-gray-800"><strong>{msg.user}:</strong> {msg.bot}</p>
                </div>
              </div>
            ))
          )}
        </div>

        {/* Query Input */}
        <div className="mt-4 w-full max-w-3xl flex">
          <input type="text" placeholder="Ask about your document..." value={chat} onChange={(e) => setChat(e.target.value)} className="w-full border p-3 rounded-l-lg shadow focus:outline-none text-lg" />
          <button onClick={handleSend} className="bg-blue-500 text-white px-6 py-3 rounded-r-lg shadow hover:bg-blue-600 transition text-lg">→</button>
        </div>
      </div>
    </div>
  );
};

export default DocBot;

